INSERT INTO mac_ulog (user_id, ulog_mid, ulog_type, ulog_rid, ulog_sid, ulog_nid, ulog_points, ulog_time)
SELECT #{userId}, #{mid}, #{type}, #{rid}, #{sid}, #{nid}, #{points}, #{now}
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM mac_ulog AS u
                  WHERE u.user_id = #{userId} AND u.ulog_mid = #{mid} AND u.ulog_type = #{type}
                    AND u.ulog_rid = #{rid} AND u.ulog_sid = #{sid} AND u.ulog_nid = #{nid}
                    AND u.ulog_points = #{points})

