UPDATE mac_user
SET user_points = user_points - #{points}
WHERE user_id = #{userId} AND user_points >= #{points}

UPDATE mac_user
SET user_points = user_points + #{points}
WHERE user_id = #{userId}

UPDATE mac_user
SET user_points = user_points - #{points}, user_points_froze = user_points_froze + #{points}
WHERE user_id = #{userId} AND user_points >= #{points}

UPDATE mac_user
SET user_points = user_points + #{points}, user_points_froze = user_points_froze - #{points}
WHERE user_id = #{userId} AND user_points_froze >= #{points}

UPDATE mac_user
SET user_points = user_points - #{points}, user_end_time = #{endTime}, group_id = #{groupId}
WHERE user_id = #{userId} AND user_points >= #{points} AND user_end_time = #{oldEndTime}
  AND group_id = #{oldGroupId}

UPDATE mac_user
SET user_points = user_points + #{points}, user_end_time = #{oldEndTime}, group_id = #{oldGroupId}
WHERE user_id = #{userId} AND user_end_time = #{endTime} AND group_id = #{groupId}

UPDATE mac_user
SET group_id = 2
WHERE group_id > 2 AND user_end_time <= #{now}

UPDATE mac_card
SET card_sale_status = 1, card_use_status = 1, card_use_time = #{now}, user_id = #{userId}
WHERE card_id = #{cardId} AND card_use_status = 0

UPDATE mac_card
SET card_use_status = 0, card_sale_status = #{oldSaleStatus}, user_id = #{oldUserId},
    card_use_time = #{oldUseTime}
WHERE card_id = #{cardId} AND card_use_status = 1 AND user_id = #{userId} AND card_use_time = #{now}

