INSERT INTO mac_visit (user_id, visit_ip, visit_ly, visit_time)
SELECT #{userId}, #{ip}, #{referer}, #{now}
FROM DUAL
WHERE (SELECT COUNT(*) FROM mac_visit AS v
       WHERE v.user_id = #{userId} AND v.visit_ip = #{ip} AND v.visit_time > #{since}) < #{max}
